function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', W1 = '#3d2814', W2 = '#8b5a2b', W3 = '#c4a06a';
  const B1 = '#c4b898', B2 = '#e8dcc0', B3 = '#6a6358';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  px(28, 34, 8, 22, O); px(30, 36, 4, 18, W2);
  px(30, 36, 4, 2, W3); px(30, 52, 4, 2, W1);
  const prong = (bx, lean) => {
    for (let i = 0; i < 22; i++) {
      const x = bx + Math.floor(lean * i * 0.15);
      const y = 30 - i;
      px(x, y, 4, 4, O); px(x + 1, y + 1, 2, 2, B2);
      if (i < 4) px(x + 1, y + 1, 2, 1, B3);
    }
  };
  prong(12, -1); prong(28, 0); prong(44, 1);
  px(14, 10, 4, 4, B2); px(30, 6, 4, 4, B2); px(46, 10, 4, 4, B2);
}
